"use client";

/**
 * "Hero dish": the photo on the website's landing page for this country, picked
 * from the food photo library (docs/design/photos/LICENSES.md). The list and the
 * thumbnails are generated by tools/photos/credits.py (make ci-photos keeps them in
 * step with the website's /food photos); it saves as the country's hero_photo setting,
 * which the API checks against the same list.
 */
import { useQueryClient } from "@tanstack/react-query";
import { useState } from "react";

import library from "@/content/photo-library.json";
import { apiError, can, type CountrySummary, marketsApi, useAdminMe } from "@/lib/markets";

const SLUGS = library as string[];

/** "south-indian-thali" -> "South indian thali" */
function dishName(slug: string): string {
  const words = slug.replace(/-/g, " ");
  return words[0].toUpperCase() + words.slice(1);
}

export function HeroDish({ country }: { country: CountrySummary }) {
  const { data: me } = useAdminMe();
  const qc = useQueryClient();
  const saved = typeof country.settings.hero_photo === "string" ? (country.settings.hero_photo as string) : null;
  const [picked, setPicked] = useState<string | null>(saved);
  const [busy, setBusy] = useState(false);
  const [problem, setProblem] = useState<string | null>(null);
  const [done, setDone] = useState(false);
  const editable = can(me, "markets.edit", country.code);

  async function save(slug: string | null) {
    setBusy(true);
    setProblem(null);
    setDone(false);
    try {
      await marketsApi.updateCountry(country.code, { settings: { hero_photo: slug } });
      await qc.invalidateQueries({ queryKey: ["markets"] });
      setPicked(slug);
      setDone(true);
    } catch (e) {
      setProblem(apiError(e));
    } finally {
      setBusy(false);
    }
  }

  return (
    <section aria-label="Hero dish" className="rounded-2xl border border-line bg-white p-6">
      <div className="flex flex-wrap items-center gap-3">
        <h2 className="m-0 flex-1 text-[17px] font-extrabold">Hero dish</h2>
        {editable && (
          <>
            <button
              type="button"
              disabled={busy || !saved}
              onClick={() => void save(null)}
              className="h-10 rounded-full px-3 text-sm font-semibold text-muted disabled:opacity-50"
            >
              Use the default
            </button>
            <button
              type="button"
              disabled={busy || !picked || picked === saved}
              onClick={() => void save(picked)}
              className="h-10 rounded-full bg-peacock px-5 text-sm font-bold text-white disabled:opacity-50"
            >
              Save hero dish
            </button>
          </>
        )}
      </div>
      <p className="mt-1 text-[13px] text-muted">
        The big photo on the website&apos;s landing page for visitors in {country.name}.{" "}
        {saved ? <>Now: <b className="text-kohl">{dishName(saved)}</b>.</> : "None chosen: the website shows its default photo."}
      </p>
      <div role="radiogroup" aria-label="Library photos" className="mt-4 grid gap-3 [grid-template-columns:repeat(auto-fill,minmax(120px,1fr))]">
        {SLUGS.map((slug) => {
          const on = picked === slug;
          return (
            <button
              key={slug}
              type="button"
              role="radio"
              aria-checked={on}
              data-slug={slug}
              disabled={!editable || busy}
              onClick={() => {
                setPicked(slug);
                setDone(false);
              }}
              className={`overflow-hidden rounded-xl border-2 bg-white text-left disabled:cursor-default ${on ? "border-peacock" : "border-transparent"}`}
            >
              {/* eslint-disable-next-line @next/next/no-img-element -- static thumbnails from the photo library */}
              <img src={`/food/${slug}-400.webp`} alt="" loading="lazy" className="block aspect-[4/3] w-full object-cover" />
              <span className="block px-2 py-1 text-xs font-semibold text-kohl">{dishName(slug)}</span>
            </button>
          );
        })}
      </div>
      {done && (
        <p role="status" className="mt-3 text-sm font-semibold text-peacock-dark">
          Saved. The website picks it up within a minute.
        </p>
      )}
      {problem && (
        <p role="alert" className="mt-3 rounded-xl bg-danger-tint p-3 text-sm text-danger-ink">
          {problem}
        </p>
      )}
    </section>
  );
}
